import sys

def can_work_together(a, b):
    return (a & b) != 0

def max_calm_group_sum(n, a, b):
    max_sum = 0
    for i in range(n):
        current_sum = b[i]
        for j in range(i + 1, n):
            if can_work_together(a[i], a[j]):
                current_sum += b[j]
                if current_sum > max_sum:
                    max_sum = current_sum
                # Reset current_sum to only include the new student j
                current_sum = b[j]
    return max_sum

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))

    result = max_calm_group_sum(n, a, b)
    print(result)

if __name__ == "__main__":
    main()
